private object BuildPowerProfile(double[] duties, bool software, object? templateOverride = null)
{
    // FAN-934 R2 §3-B：唯一自测 HC 边界（默认关闭）。生产路径 hcBoundaryForSelfTest
    // 恒为 null，走下方真实 HC FanMode/FanProfile 构造。
    if (hcBoundaryForSelfTest is { } selfTestProfileBoundary && templateOverride is null)
        return selfTestProfileBoundary.BuildProfile(duties, software);
    var fanModeType = FindType("HandheldCompanion.Misc.FanMode")
        ?? throw new MissingMemberException("HC FanMode not found");
    var template = templateOverride ?? hcProfileTemplate;
    if (template is null)
        throw new InvalidOperationException("HC power-profile context was not captured before fan control");
    // Clone HC's own device profile rather than constructing a new one.
    // Device callbacks may use Guid/OEMPowerMode alongside FanProfile.
    var profile = CloneHcPowerProfilePreservingFanState(template);
    var fan = GetMember(profile, "FanProfile");
    if (fan is null) throw new InvalidOperationException("HC FanProfile construction failed");
    // Keep the profile's original HC FanProfile object and its public
    // smoothing/Tjmax settings. Only replace the 11-point curve through
    // HC's own validation method; do not synthesize a parallel profile.
    if (duties.Length == 11)
        Invoke(fan, "SetFanSpeed", duties);
    SetMember(fan, "fanMode", Enum.Parse(fanModeType, software ? "Software" : "Hardware"));
    SetMember(profile, "FanProfile", fan);
    return profile;
}

