recoveryTimer = new Timer(_ =>
{
    lock (gate)
    {
        recoveryTimer?.Dispose();
        recoveryTimer = null;
        if (stopped || (state.State != "FaultLocked" && state.State != "AwaitingCloseCleanup")) return;
        if (recoveryRetryWindowStartedMonoMs == 0 ||
            MonoMs() - recoveryRetryWindowStartedMonoMs >= EffectiveRecoveryRetryWindowMs)
        {
            EnterRecoveryRetryTerminalState(recoveryReopenRequired
                ? "reopen-not-completed-within-cycle-budget"
                : "recovery retry window elapsed");
            return;
        }
        var strictSystemPendingRetry = recoveryRetryUsesSystemPendingClose;
        // B4（FAN-925 / HC 回函 A1–A3）：route-lost 时宿主**自身出清不了**——
        // `Device_Inserted(true)` 绕过 PnP 重放 + VID/PID 过滤 + 状态门，须由调用方自证
        // "设备在场"，且 HC 侧没有任何"等 HID 稳定"步骤（等待是调用方责任）
        // ⇒ **重开归 bridge**。这里改成"有界等待重开收据"，不再空转被第五道门挡住的 restore。
        // 判据只用**收据**（A1/A5/H4）：`OpenEvents()` 返回 / `IsReady()` / `IsConnected` /
        // `OpenCalled` / `OpenEventsCalled` **都不算**——H4 已源码级证明后两者只代表"已发起"。
        // 等待是静默的（不逐轮记日志，遵守"事件=低频"）。
        var reopenReceiptDetail = "not-required";
        if (recoveryReopenRequired)
        {
            // §4.5（FAN-925B）：明确**谁在页面不可用期间驱动 Fan 恢复**，并保证
            // "永远等旧页面"不是自动恢复实现：有界等待 → 复用既有受控更换升级路径
            // （至多一次/周期）；本宿主在此期间保持唯一写入权，不自起第二个 owner。
            var waited = Math.Max(0, Environment.TickCount64 - reopenWaitStartedMonoMs);
            var decision = ReopenOwnershipDecision(
                reopenRequired: true,
                waitedMs: waited,
                budgetMs: EffectiveReopenBridgeWaitBudgetMs,
                replacementAlreadyRequested: controlledReplacementRequested);
            if (!string.Equals(decision, recoveryOwner, StringComparison.Ordinal))
            {
                recoveryOwner = decision;
                var requestsReplacement = decision == "fan-host-requests-controlled-replacement";
                if (requestsReplacement)
                {
                    // §4.1（FAN-926 P2）：**先**做恰好一次"有正式 HC 生命周期收据证明
                    // 的同进程恢复"；只有拿不到完整收据时才允许请求一次受控更换。
                    if (uiFreeSelfOpenAttempts == 0)
                    {
                        uiFreeSelfOpenAttempts++;
