                                reopenCount = recoveryReopenCount,
                                cycleId = recoveryCycle?.CycleId,
                                selfOpenAttempts = uiFreeSelfOpenAttempts,
                                scope = "ui-free-same-process-stage-only",
                            });
                            reopenBinding = null;
                            state.State = state.PowerState == "Suspended" ? "Suspended" : "AwaitingControl";
                            return;
                        }
                    }
                    controlledReplacementRequested = true;
                    controlledReplacementRequests++;
                    uiFreeReplacementRequests++;
                    // §4.1（FAN-926 P2）：恰好一次受控更换。拉起成功**不等于**恢复成功——
                    // 恢复由后继实例的"旧实例已退出"自证 + 正式收据证明。
                    _ = TryRequestControlledHostReplacementLocked();
